from __future__ import annotations


def student_ui_html() -> str:
    """Interactive, dependency-free student memory workspace."""
    return r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>数学记忆 · 错题回访</title>
<style>
:root{--ink:#17243a;--muted:#657186;--paper:#fbfaf7;--card:#fff;--line:#e3e5e8;--brand:#176b68;--brand-dark:#105451;--soft:#e9f3f1;--warm:#fff3d8;--danger:#a44235;--shadow:0 12px 32px rgba(28,39,56,.07)}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:"Microsoft YaHei","PingFang SC",Segoe UI,sans-serif;line-height:1.65}
button,input{font:inherit}button{cursor:pointer}.topbar{height:68px;border-bottom:1px solid var(--line);background:rgba(251,250,247,.96);display:flex;align-items:center;justify-content:space-between;padding:0 max(24px,calc((100vw - 1220px)/2));position:sticky;top:0;z-index:5}
.brand{display:flex;align-items:center;gap:11px;font-weight:750;letter-spacing:.02em}.mark{width:34px;height:34px;border-radius:10px;background:var(--brand);color:white;display:grid;place-items:center;font-family:Georgia,serif;font-size:20px}.lab{font-size:12px;color:var(--brand);background:var(--soft);padding:4px 9px;border-radius:999px}
main{max-width:1220px;margin:auto;padding:58px 24px 80px}.hero{max-width:850px;margin:0 auto 38px;text-align:center}.eyebrow{color:var(--brand);font-size:13px;font-weight:700;letter-spacing:.12em}.hero h1{font-size:clamp(30px,5vw,50px);line-height:1.16;margin:12px 0 14px;letter-spacing:-.035em}.hero p{color:var(--muted);font-size:17px;margin:0 auto 26px;max-width:700px}
.ask{display:flex;gap:10px;background:var(--card);border:1px solid #ccd4d3;border-radius:18px;padding:9px;box-shadow:var(--shadow);text-align:left}.ask:focus-within{border-color:var(--brand);outline:3px solid rgba(23,107,104,.1)}.ask input{flex:1;border:0;outline:0;padding:13px 15px;color:var(--ink);min-width:0;background:transparent}.ask button{border:0;border-radius:12px;background:var(--brand);color:white;padding:12px 22px;font-weight:700}.ask button:hover{background:var(--brand-dark)}.ask button:disabled{opacity:.65;cursor:wait}
.examples{display:flex;justify-content:center;gap:8px;flex-wrap:wrap;margin-top:14px}.chip{border:1px solid var(--line);background:transparent;color:var(--muted);border-radius:999px;padding:7px 12px;font-size:13px}.chip:hover{border-color:var(--brand);color:var(--brand);background:var(--soft)}
.hidden{display:none!important}.loading{max-width:850px;margin:38px auto;text-align:center;color:var(--muted)}.spinner{width:28px;height:28px;margin:0 auto 12px;border:3px solid var(--line);border-top-color:var(--brand);border-radius:50%;animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}
.errorbox,.empty{max-width:780px;margin:34px auto;background:white;border:1px solid var(--line);border-radius:18px;padding:34px;text-align:center}.errorbox{border-color:#e3beb8;color:var(--danger)}.empty h2{margin-top:0}.empty p{color:var(--muted)}
.result-head{display:flex;justify-content:space-between;gap:22px;align-items:flex-end;margin-bottom:20px}.result-head h2{font-size:27px;margin:0 0 4px}.result-head p{margin:0;color:var(--muted)}.meta{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}.pill{display:inline-flex;align-items:center;border-radius:999px;background:#eef1f3;color:#526174;padding:5px 10px;font-size:12px}.pill.good{background:var(--soft);color:var(--brand-dark)}
.overview{display:grid;grid-template-columns:1.15fr .85fr;gap:16px;margin:18px 0 34px}.panel{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:21px}.panel h3{font-size:16px;margin:0 0 15px}.weak-summary{margin:-3px 0 16px;padding:13px 15px;border-left:4px solid var(--brand);border-radius:8px;background:var(--soft);color:#365451;font-size:14px;line-height:1.75}.weak-summary small{display:block;margin-top:5px;color:var(--brand);font-size:11px}.weak-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.weak{background:#f6f8f7;border-radius:12px;padding:13px}.weak strong{display:block;font-size:14px}.weak small{color:var(--muted)}.score{color:var(--brand);font-weight:800;font-size:20px;float:right}.bar{height:5px;background:#dde7e5;border-radius:5px;margin-top:10px;overflow:hidden}.bar span{display:block;height:100%;background:var(--brand);border-radius:5px}.reason-list{display:grid;gap:11px}.reason-row{display:grid;grid-template-columns:1fr auto;gap:12px;align-items:center}.reason-label{display:flex;justify-content:space-between;font-size:13px}.reason-track{height:7px;background:#edf0f2;border-radius:6px;overflow:hidden}.reason-track span{display:block;height:100%;background:#d5954b}.count{font-size:12px;color:var(--muted)}
.section-title{display:flex;align-items:center;justify-content:space-between;margin:34px 0 14px}.section-title h2{font-size:23px;margin:0}.cards{display:grid;gap:22px}.case{background:var(--card);border:1px solid var(--line);border-radius:20px;overflow:hidden;box-shadow:0 8px 24px rgba(28,39,56,.045)}.case-head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;padding:20px 22px;border-bottom:1px solid var(--line)}.case-head h3{margin:4px 0 0;font-size:18px}.case-no{font-size:12px;color:var(--brand);font-weight:800;letter-spacing:.08em}.case-body{padding:22px}.visuals{display:grid;grid-template-columns:1fr;gap:22px;align-items:start}.figure{margin:0;background:#f4f4f2;border-radius:12px;overflow:hidden;border:1px solid var(--line)}.figure img{display:block;width:100%;height:auto;object-fit:contain;background:white}.audit-figure{border-color:#b8d7d2;box-shadow:0 10px 28px rgba(23,107,104,.1)}.audit-figure a{display:block;background:white}.audit-figure img{height:auto;cursor:zoom-in}.audit-figure figcaption{font-weight:700;color:var(--brand-dark);background:#f0f8f6}.figure figcaption{padding:10px 13px;color:var(--muted);font-size:12px;border-top:1px solid var(--line)}.insight{display:grid;grid-template-columns:1fr;gap:14px;margin-top:16px}.box{background:#f7f8f8;border-radius:12px;padding:16px}.box h4{display:inline;font-size:16px;margin:0;color:var(--ink)}.box p{margin:10px 0 0;white-space:pre-wrap}.error-type{display:inline-block;margin-left:9px;font-size:12px;color:var(--danger);background:#fae9e6;border-radius:999px;padding:3px 8px}.solution-panel{margin-top:16px;background:linear-gradient(145deg,#e8f5f2,#f5fbf9);border:1px solid #bfded8;border-left:5px solid var(--brand);border-radius:14px;padding:20px}.solution-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:12px}.solution-head h4{font-size:17px;color:var(--brand-dark);margin:0}.solution-content{display:grid;gap:10px}.solution-step{background:rgba(255,255,255,.72);border:1px solid #d1e7e2;border-radius:11px;padding:13px 15px}.step-label{font-size:12px;font-weight:700;color:var(--brand-dark)}.step-formula{text-align:center;font-size:18px;overflow-x:auto;padding:5px}.step-explanation{margin:4px 0 0;color:var(--muted);font-size:13px}.final-answer{margin-top:16px;padding:12px 14px;background:white;border:1px solid #c9e2dd;border-radius:10px;font-size:16px}.verification{font-size:12px;color:var(--brand-dark);background:white;padding:5px 9px;border-radius:999px}.tags{display:flex;gap:6px;flex-wrap:wrap;margin-top:12px}.tag{font-size:12px;background:#eef1f3;border-radius:6px;padding:4px 8px;color:#536174}.case details{margin-top:15px;border-top:1px dashed var(--line);padding-top:12px}.case summary{cursor:pointer;color:var(--muted);font-size:13px}.steps{white-space:pre-wrap;font-size:13px;color:#4b586b}.review{display:flex;justify-content:flex-end;margin-top:20px;padding-top:16px;border-top:1px solid var(--line)}.review a{font-size:13px;color:var(--brand);text-decoration:none;font-weight:700}.review a:hover{text-decoration:underline}
.audit{margin:26px 0 0;color:var(--muted);font-size:12px}.audit summary{cursor:pointer}.trace{display:flex;gap:8px;flex-wrap:wrap;margin-top:9px}.trace span{background:#eef1f3;border-radius:6px;padding:4px 8px}.footer{text-align:center;color:#8a929e;font-size:12px;margin-top:54px}
@media(max-width:820px){main{padding:35px 15px 60px}.topbar{padding:0 16px}.overview,.visuals,.insight{grid-template-columns:1fr}.figure img,.audit-figure img{height:auto}.result-head{display:block}.meta{justify-content:flex-start;margin-top:12px}.weak-grid{grid-template-columns:1fr}.ask{border-radius:14px}.ask button{padding:11px 14px}.solution-head{align-items:flex-start;flex-direction:column}}
</style>
<script>
window.MathJax={
  tex:{inlineMath:[['\\(','\\)'],['$','$']],displayMath:[['\\[','\\]'],['$$','$$']],processEscapes:true},
  options:{skipHtmlTags:['script','noscript','style','textarea','pre','code']},
  startup:{typeset:false}
};
</script>
<script defer src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js" onload="typesetMath()"></script>
</head><body>
<header class="topbar"><div class="brand"><span class="mark">∫</span><span>数学记忆智能体</span></div></header>
<main><section class="hero"><div class="eyebrow">错题回访与薄弱点整理</div><h1>从过去的解题中，找到下一步</h1><p>用一句话查询你的手写数学记忆。系统会整理错因、找回对应错题，并展示经过验证的订正。</p>
<form class="ask" id="queryForm"><input id="query" aria-label="输入错题查询" value="帮我整理过去三月的微积分错题" autocomplete="off"><button id="submit" type="submit">开始整理</button></form>
<div class="examples"><button class="chip" data-q="帮我整理过去七个月的概率统计错题">概率统计</button><button class="chip" data-q="帮我整理过去七个月的三角学错题">三角学</button><button class="chip" data-q="帮我整理过去七个月的几何错题">几何学</button><button class="chip" data-q="帮我整理过去三个月的微积分错题">微积分</button><button class="chip" data-q="整理我的代数错题">代数</button><button class="chip" data-q="找出我最薄弱的知识点">薄弱知识点</button></div></section>
<section id="loading" class="loading hidden"><div class="spinner"></div><div>正在检索解题记忆并整理证据…</div></section>
<section id="error" class="errorbox hidden"></section><section id="empty" class="empty hidden"><h2>暂时没有找到匹配错题</h2><p id="emptyText"></p></section><section id="results" class="hidden"></section>
<div class="footer">所有结论均保留来源证据；教师修订不会改变 FERMAT 离线评测真值。</div></main>
<script>
const $=id=>document.getElementById(id), esc=value=>String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const domainName={clc:'微积分',alg:'代数',art:'算术',mgm:'几何',pst:'概率与统计',trg:'三角',apt:'综合能力'};
const errorName={conceptual:'概念错误',assumption:'错误假设',algebraic_manipulation:'代数变形错误',arithmetic:'计算错误',notation:'符号错误',transcription:'誊写错误',omitted_step:'步骤遗漏',presentation:'表达问题',no_actual_error:'实际无错',uncertain:'不确定'};
function looksLikeMath(text){return /[=≈≠≤≥∫∑√∞^_]|\\(?:frac|sqrt|int|sum|lim|begin|left|right|cdot|times)|(?:\d|[a-zA-Z])\s*[+\-*/]\s*(?:\d|[a-zA-Z])/u.test(text)}
function standaloneMath(text){const words=text.match(/[A-Za-z]{3,}/g)||[],chinese=text.match(/[\u4e00-\u9fff]/g)||[];return looksLikeMath(text)&&words.length<=2&&chinese.length<=4}
function inlinePowers(text){const pattern=/[A-Za-z](?:_\{[^}]+\}|\^\{[^}]+\}|_[A-Za-z0-9]+|\^[A-Za-z0-9+\-]+)+(?:\([^)]*\))?/g;let html='',cursor=0,match;while((match=pattern.exec(text))!==null){html+=esc(text.slice(cursor,match.index))+`<span class="math-source">\\(${esc(match[0])}\\)</span>`;cursor=match.index+match[0].length}return html+esc(text.slice(cursor))}
function mathRich(value){const text=String(value??'').trim();if(!text)return '';return text.split(/\r?\n/).map(line=>{const trimmed=line.trim();if(!trimmed)return '<br>';if(/\$|\\\(|\\\[/.test(trimmed))return esc(trimmed);const colon=trimmed.search(/[：:]/),tail=colon>=0?trimmed.slice(colon+1).trim():'';if(tail&&standaloneMath(tail))return `${esc(trimmed.slice(0,colon+1))} <span class="math-source">\\(\\displaystyle ${esc(tail)}\\)</span>`;if(standaloneMath(trimmed))return `<span class="math-source">\\(\\displaystyle ${esc(trimmed)}\\)</span>`;return inlinePowers(trimmed)}).join('<br>')}
function mathFormula(value){const text=String(value??'').trim();if(!text)return '';if(/\$|\\\(|\\\[/.test(text))return esc(text);return `<span class="math-source">\\(\\displaystyle ${esc(text)}\\)</span>`}
function correctionSteps(correction){const steps=correction?.corrected_steps||[];if(!steps.length)return `<div>${mathRich(correction?.corrected_solution||'该题尚无可用订正。')}</div>`;return steps.map((step,index)=>`<div class="solution-step"><div class="step-label">步骤 ${index+1}</div><div class="step-formula">\\[\\displaystyle ${esc(step.latex||'')}\\]</div>${step.explanation?`<p class="step-explanation">${esc(step.explanation)}</p>`:''}</div>`).join('')}
function typesetMath(){const root=$('results');if(!root||root.classList.contains('hidden')||!window.MathJax?.typesetPromise)return;try{window.MathJax.typesetClear?.([root]);window.MathJax.typesetPromise([root]).catch(()=>{})}catch(_){}}
function setState(name){['loading','error','empty','results'].forEach(id=>$(id).classList.toggle('hidden',id!==name))}
function shortDate(value){if(!value)return '时间未知';const d=new Date(value);return Number.isNaN(d.getTime())?value:`${d.getFullYear()}年${d.getMonth()+1}月${d.getDate()}日`}
function timeLabel(window,months){if(!months)return '全部时间';if(!window?.time_from)return `最近${months}个月`;return `${shortDate(window.time_from)} — ${shortDate(window.time_to)}`}
function errorSummary(items){const counts={};items.forEach(x=>{const key=x.error_type_effective||x.error_type_pred||'uncertain';counts[key]=(counts[key]||0)+1});return Object.entries(counts).sort((a,b)=>b[1]-a[1])}
function renderOverview(data){const weak=(data.weaknesses||[]).slice(0,4),summary=data.weakness_summary||{},reasons=errorSummary(data.evidence||[]),max=Math.max(1,...reasons.map(x=>x[1])),summaryHtml=summary.text?`<div class="weak-summary">${esc(summary.text)}<small>依据：Seed 大模型诊断与历史薄弱度</small></div>`:'';return `<div class="overview"><section class="panel"><h3>薄弱知识点</h3>${summaryHtml}<div class="weak-grid">${weak.length?weak.map(x=>`<div class="weak"><span class="score">${Number(x.weakness_score||0).toFixed(0)}</span><strong>${esc(x.knowledge_point)}</strong><small>${x.error_count}/${x.attempt_count} 次错误</small><div class="bar"><span style="width:${Math.min(100,Number(x.weakness_score||0))}%"></span></div></div>`).join(''):'<div class="weak"><strong>样本不足</strong><small>完成更多 VLM 诊断后生成薄弱点</small></div>'}</div></section><section class="panel"><h3>本次错因分布</h3><div class="reason-list">${reasons.map(([name,count])=>`<div class="reason-row"><div><div class="reason-label"><span>${esc(errorName[name]||name)}</span><span class="count">${count} 次</span></div><div class="reason-track"><span style="width:${count/max*100}%"></span></div></div></div>`).join('')}</div></section></div>`}
function imageBlock(item){const id=encodeURIComponent(item.attempt_id),model=encodeURIComponent(item.model),audit=`/v1/attempts/${id}/audit?model=${model}`;return `<div class="visuals"><figure class="figure"><img loading="lazy" src="/v1/attempts/${id}/image" alt="原始手写数学作答"><figcaption>原始手写作答</figcaption></figure><figure class="figure audit-figure"><a href="${audit}" target="_blank" title="点击查看原尺寸标注图"><img loading="lazy" src="${audit}" alt="可审计订正图"></a><figcaption>错误定位与正确结果 · 点击查看大图</figcaption></figure></div>`}
function caseCard(item,index){const correction=item.correction,points=item.knowledge_points||[],review=item.review?'<span class="pill good">教师已修订</span>':'',verification=correction?.verification_status||'尚未提供',errorType=errorName[item.error_type_effective||item.error_type_pred]||'未分类',steps=(item.steps||[]).map(s=>`${s.step_index+1}. ${s.transcription}`).join('\n');return `<article class="case"><header class="case-head"><div><div class="case-no">错题 ${String(index+1).padStart(2,'0')}</div><h3>${mathRich(item.question_transcription||item.orig_q||item.attempt_id)}</h3></div><div class="meta"><span class="pill">${esc(shortDate(item.Time))}</span>${review}</div></header><div class="case-body">${imageBlock(item)}<div class="tags">${points.map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div><div class="insight"><div class="box"><h4>错题原因分析</h4><span class="error-type">${esc(errorType)}</span><p>${mathRich(item.error_explanation||'模型暂未提供诊断结果')}</p></div></div><section class="solution-panel"><div class="solution-head"><h4>正确思路与结果</h4><span class="verification">验证状态：${esc(verification)}</span></div><div class="solution-content">${correctionSteps(correction)}</div>${correction?.final_answer?`<div class="final-answer"><strong>最终答案：</strong> ${mathRich(correction.final_answer)}</div>`:'<div class="final-answer">最终答案尚未提供</div>'}</section><details><summary>查看模型转写与解题步骤</summary><p class="steps">${mathRich(steps||item.solution_transcription||'暂无步骤')}</p></details><div class="review"><a href="/review?attempt_id=${encodeURIComponent(item.attempt_id)}&model=${encodeURIComponent(item.model)}">教师修改 VLM 诊断或订正 →</a></div></div></article>`}
function render(data){const evidence=data.evidence||[],plan=data.plan||{};if(!evidence.length){$('emptyText').textContent=`当前模型“${data.model||'未知'}”还没有符合条件的诊断记忆。字节 VLM 接入并回填后，可用同一问题直接复测。`;setState('empty');return}const title=domainName[plan.domain_code]||'数学';$('results').innerHTML=`<header class="result-head"><div><h2>${esc(title)}错题整理</h2><p>找到 ${evidence.length} 道相关错题，并按证据相关性排序。</p></div><div class="meta"><span class="pill good">${esc(timeLabel(data.resolved_time_window,plan.recent_months))}</span><span class="pill">${esc(data.model)}</span></div></header>${renderOverview(data)}<div class="section-title"><h2>错题回访与订正</h2><span class="pill">共 ${evidence.length} 题</span></div><div class="cards">${evidence.map(caseCard).join('')}</div><details class="audit"><summary>查看本次查询依据</summary><div class="trace">${(data.tool_trace||[]).map(x=>`<span>${esc(x.tool)} · ${x.result_count}</span>`).join('')}<span>${esc(data.search_backend)}</span></div></details>`;setState('results');document.querySelectorAll('.audit-figure img').forEach(img=>img.onerror=()=>img.closest('.audit-figure').classList.add('hidden'));typesetMath()}
async function runQuery(text){const q=text.trim();if(!q)return;$('query').value=q;$('submit').disabled=true;setState('loading');try{const response=await fetch('/v1/memory/query',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({request:q,limit:500})}),data=await response.json();if(!response.ok)throw Error(data.error||'查询失败');render(data);history.replaceState(null,'',`?q=${encodeURIComponent(q)}`)}catch(error){$('error').textContent=`查询失败：${error.message}`;setState('error')}finally{$('submit').disabled=false}}
$('queryForm').addEventListener('submit',event=>{event.preventDefault();runQuery($('query').value)});document.querySelectorAll('.chip').forEach(button=>button.onclick=()=>runQuery(button.dataset.q));const initial=new URLSearchParams(location.search).get('q');if(initial)runQuery(initial);
</script></body></html>'''
